			"category",
			"category",
			"category",
			"category",
			"conversation",
			"conversation",
			"conversation",
			"separator",
			"total",
			"resource-header",
			"resource", // skills (2):
			"resource", //   - docx
			"resource", //   - pdf
			"resource", // plugins (1):
