			"resource", // mcps (1):
			"resource", //   - github [~/.agents/mcp.json]
		]);
	});

	it("text matches buildPanelLines output", () => {
		expect(buildPanelRows(data).map((r) => r.text)).toEqual(buildPanelLines(data));
